<?php require_once 'config/db.php'; require_once 'includes/auth.php'; if(!empty($_SESSION['user'])){header('Location:index.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=trim($_POST['email']??'');$pass=$_POST['password']??'';$s=$conn->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->bind_param('s',$email);$s->execute();$u=$s->get_result()->fetch_assoc(); if($u && password_verify($pass,$u['password'])){$_SESSION['user']=$u;header('Location:index.php');exit;} $err='Invalid email or password.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OMS Login</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="container" style="max-width:480px;margin-top:70px"><div class="card"><h1>Order Management System</h1><p>Login to continue</p><?php if($err):?><div class="error"><?=h($err)?></div><?php endif;?><form method="post"><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button class="btn" type="submit">Login</button></form><p>New customer? <a href="register.php">Create an account</a></p><hr><small>First-time setup: open <a href="setup.php">setup.php</a> once to create admin. Admin: admin@oms.com / admin123</small></div></div></body></html>